import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { deleteSpaceAction } from "../handlers/deleteSpaceAction";
import type { ApiError } from "../runtime/client";
import type { SpacePartition } from "../types/SpacePartition";

type Data = Awaited<ReturnType<typeof deleteSpaceAction>>;
type Vars = { spaceId: SpacePartition; actionId: string };

export function useDeleteSpaceAction(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => deleteSpaceAction(vars.spaceId, vars.actionId),
    ...options,
  });
}
